export async function runOrchestration(
  initialState: AgentState,
  dependencies: OrchestrationDependencies,
  options: OrchestrationOptions = {},
): Promise<OrchestrationResult> {
  const workerSelection = initialState.workerSelection;
  const codexNetworkAccess = initialState.codexNetworkAccess;
  const maxIterations = options.maxIterations ?? MAX_ORCHESTRATION_ITERATIONS;
  if (!Number.isInteger(maxIterations) || maxIterations < 1 || maxIterations > MAX_ORCHESTRATION_ITERATIONS) {
    throw new Error(`Iteration limit must be between 1 and ${MAX_ORCHESTRATION_ITERATIONS}.`);
  }

  const startIteration = options.startIteration ?? 1;
  if (!Number.isInteger(startIteration) || startIteration < 1 || startIteration > maxIterations ||
      (startIteration > 1 && initialState.iteration !== startIteration - 1)) {
    throw new Error('The initial iteration does not match the preserved run budget.');
  }
  const metrics = createRunMetrics(options.initialInspectionMs, options.resumeReviewWaitMs);
  if (options.initialEvaluationRecoveryApproved) metrics.counts.evaluationRecoveries = 1;
  const trace: { path: string; runId: string; savedRunId?: string; segment?: number } = {
    ...await createOrchestrationTrace(initialState.repo.root),
    ...(options.savedRunId ? { savedRunId: options.savedRunId, segment: options.segment ?? 1 } : {}),
  };
  const execute = dependencies.execute ?? executeCandidate;
  const inspect = dependencies.inspect ?? inspectRepo;
  let state = initialState;
  let lastSummary = metrics.summary(state);
      iterations: interruptedIteration,
      exitCode: 1,
      summary,
      persistenceFailure: error.eventType,
    };
  };
  try {
    throwIfInterrupted(options.signal);

    for (let iteration = startIteration; iteration <= maxIterations; iteration += 1) {
      throwIfInterrupted(options.signal);
      state = { ...state, iteration };
      if (workerSelection === undefined) delete state.workerSelection;
      else state.workerSelection = workerSelection;
      if (codexNetworkAccess === undefined) delete state.codexNetworkAccess;
      else state.codexNetworkAccess = codexNetworkAccess;
      interruptedIteration = iteration;
      stateBefore = state;
      evaluation = null;
      policy = null;
      interruptedProposal = null;
      interruptedApproval = null;
      interruptedInput = null;
      interruptedResult = null;
      interruptedWorkerRequest = undefined;
      phase = 'evaluation';
      await record({ type: 'iteration_reserved', iteration }, state);
      throwIfInterrupted(options.signal);
      try {
        evaluation = await metrics.measure('evaluationMs', () => interruptible(() => {
          metrics.counts.evaluations += 1;
          return dependencies.evaluate(state, executionOptions);
        }, options.signal));
      } catch (error) {
        throwIfInterrupted(options.signal);
        if (error instanceof RunInterruptedError) throw error;
        metrics.counts.evaluationFailures += 1;
        const failure = evaluationFailure(error);
        state = {
          ...state,
          currentGoal: 'Evaluation failed; explicit continuation is required.',
          options.codexNetworkAccess === true,
        ),
        state,
      });
      savedRunId = runId;
    }
    const evaluate = configuration ? createEvaluator(configuration) : mockEvaluation;

    prompts.header('Dev Orchestrator — approval-gated orchestration', [
      `Repo: ${oneLine(repo.root)}`, `Task: ${oneLine(options.task)}`,
      `Mode: ${options.mock ? 'mock' : `live (${configuration?.provider ?? 'interrupted'})`}`,
      ...(configuration ? [`Provider: ${configuration.provider}`, `Requested model: ${oneLine(configuration.model)}`] : []),
      ...(savedRunId ? [`Saved run: ${savedRunId} (active)`] : []),
      `Worker selection: ${options.workerSelection ?? 'Codex or Claude'}`,
      ...(options.codexNetworkAccess ? ['Codex command network: enabled; workspace file sandbox retained.'] : []),
      'No repository action runs without approval.',
    ]);

    const result = await runOrchestration(state, {
      evaluate: async (currentState) => prompts.phase('Evaluating task', async () => evaluate(currentState, executionOptions), executionOptions),
      approve: async (context) => promptForApproval(prompts, context, executionOptions),
      askForInformation: async () => prompts.question('Provide the required information: ', executionOptions),
      recoverEvaluation: async (context) => promptForEvaluationRecovery(prompts, context, executionOptions),
      execute: async (proposal, runner, execution = {}) => prompts.phase(`Approved ${proposal.action}`,
        () => executeCandidate(proposal, runner, execution), execution, (result) => result.ok),
    }, {
      signal: controller.signal,
      initialInspectionMs,
      resumeReviewWaitMs,
      ...(position?.recoveryRequired ? { initialEvaluationRecoveryApproved: true } : {}),
      ...(position && previous ? { startIteration: position.nextIteration, segment: position.segment, maxIterations: previous.checkpoint.iterationLimit } : {}),
      ...(savedRunId ? { savedRunId } : {}),
      ...(controller.signal.aborted ? { initialPhase: 'inspection' as const } : {}),
      ...(savedRunId ? {
        persistence: {
          record: async (event: SavedRunEventInput, currentState: AgentState) => {
            const snapshot = event.type === 'run_stopped' && event.resumable && savedRepository
              ? await captureRepositorySnapshot(savedRepository) : undefined;
            return savedRunStore!.append(savedRunId!, event, currentState, snapshot);

